'use client';
/* GENERATED by the wire closure (2026-11-15): one named list hook +
   mutation set per bank table the audit counted as hook-less.
   Tables whose domain route was generated in the same pass point at
   /api/bank/data; the rest use the generic /api/v1/data surface.
   Both run through the shared data layer (lib/dataRoute.ts). */
import { useTableList, tableMutations } from '@/hooks/useTableData';

export function useBankAccounts(query?: Record<string, string>) {
  return useTableList('bank_accounts', query, '/api/v1/data');
}
export const bankAccountsMutations = () => tableMutations('bank_accounts', '/api/v1/data');
export function useBankTransactions(query?: Record<string, string>) {
  return useTableList('bank_transactions', query, '/api/v1/data');
}
export const bankTransactionsMutations = () => tableMutations('bank_transactions', '/api/v1/data');
